import React, { useState, useEffect, useRef, useCallback } from 'react';
import axios from 'axios';
import './App.css';

const API_BASE = 'http://localhost:5000/api';

// ============ API SERVICE ============
const api = {
  get: (endpoint) => axios.get(`${API_BASE}${endpoint}`).then(res => res.data),
  post: (endpoint, data) => axios.post(`${API_BASE}${endpoint}`, data).then(res => res.data),
  put: (endpoint, data) => axios.put(`${API_BASE}${endpoint}`, data).then(res => res.data),
  delete: (endpoint) => axios.delete(`${API_BASE}${endpoint}`).then(res => res.data)
};

// ============ APP ============
function App() {
  // State
  const [unlocked, setUnlocked] = useState(false);
  const [pin, setPin] = useState('9999');
  const [view, setView] = useState('feed');
  const [posts, setPosts] = useState([]);
  const [contacts, setContacts] = useState([]);
  const [sosLog, setSosLog] = useState([]);
  const [category, setCategory] = useState('all');
  const [anonId, setAnonId] = useState('Anon-' + Math.random().toString(36).substr(2, 8));
  const [toastMsg, setToastMsg] = useState('');
  const [showToast, setShowToast] = useState(false);
  const [showPostModal, setShowPostModal] = useState(false);
  const [postCategory, setPostCategory] = useState('mental');
  const [postText, setPostText] = useState('');
  const [showConfirm, setShowConfirm] = useState(false);
  const [confirmData, setConfirmData] = useState({ title: '', sub: '', onConfirm: null });
  const [sosLocation, setSosLocation] = useState(null);
  const [sosStatus, setSosStatus] = useState('Tap the button — I\'ll grab your GPS location and prepare it to send to your emergency contacts.');
  
  // Calculator state
  const [calcDisplay, setCalcDisplay] = useState('0');
  const [calcPrev, setCalcPrev] = useState(null);
  const [calcOp, setCalcOp] = useState(null);
  const [calcWaiting, setCalcWaiting] = useState(false);
  const [calcSecret, setCalcSecret] = useState('');
  const [calcGlow, setCalcGlow] = useState(false);

  // PIN Change State
  const [showPinModal, setShowPinModal] = useState(false);
  const [newPin, setNewPin] = useState('');
  const [confirmPin, setConfirmPin] = useState('');
  const [pinError, setPinError] = useState('');

  // Reply state
  const [openReplies, setOpenReplies] = useState({});
  const [replyDrafts, setReplyDrafts] = useState({});

  const mapRef = useRef(null);

  // ============ TOAST ============
  const toast = (msg) => {
    setToastMsg(msg);
    setShowToast(true);
    setTimeout(() => setShowToast(false), 2500);
  };

  // ============ LOAD DATA ============
  const loadData = useCallback(async () => {
    try {
      const [postsData, contactsData, logsData] = await Promise.all([
        api.get('/posts'),
        api.get('/contacts'),
        api.get('/soslogs')
      ]);
      setPosts(postsData);
      setContacts(contactsData);
      setSosLog(logsData);
    } catch (err) {
      console.error('Failed to load data:', err);
      toast('Failed to load data. Is the server running?');
    }
  }, []);

  // Load PIN
  useEffect(() => {
    api.get('/config').then(data => setPin(data.pin)).catch(console.error);
  }, []);

  // ============ CALCULATOR ============
  const calcPress = (key) => {
    if (key === 'ac') {
      setCalcDisplay('0');
      setCalcPrev(null);
      setCalcOp(null);
      setCalcWaiting(false);
      setCalcSecret('');
      return;
    }

    if (key === '=') {
      if (calcSecret === pin) {
        setUnlocked(true);
        setCalcDisplay('0');
        setCalcSecret('');
        setCalcPrev(null);
        setCalcOp(null);
        setCalcWaiting(false);
        loadData();
        return;
      }
      if (calcOp && !calcWaiting) {
        const num = parseFloat(calcDisplay);
        let result;
        switch(calcOp) {
          case '+': result = calcPrev + num; break;
          case '-': result = calcPrev - num; break;
          case '×': result = calcPrev * num; break;
          case '÷': result = num === 0 ? NaN : calcPrev / num; break;
          default: result = num;
        }
        setCalcDisplay(isNaN(result) ? 'Error' : String(result));
        setCalcPrev(null);
        setCalcOp(null);
        setCalcWaiting(false);
        setCalcSecret('');
        return;
      }
      setCalcSecret('');
      return;
    }

    if (/^[0-9]$/.test(key)) {
      setCalcSecret(calcSecret + key);
      if (calcWaiting) {
        setCalcDisplay(key);
        setCalcWaiting(false);
      } else {
        setCalcDisplay(calcDisplay === '0' ? key : calcDisplay + key);
      }
      return;
    }

    if (key === '.') {
      if (calcWaiting) {
        setCalcDisplay('0.');
        setCalcWaiting(false);
        return;
      }
      if (!calcDisplay.includes('.')) {
        setCalcDisplay(calcDisplay + '.');
      }
      return;
    }

    if (['+', '-', '×', '÷'].includes(key)) {
      const num = parseFloat(calcDisplay);
      if (calcOp && !calcWaiting) {
        let result;
        switch(calcOp) {
          case '+': result = calcPrev + num; break;
          case '-': result = calcPrev - num; break;
          case '×': result = calcPrev * num; break;
          case '÷': result = num === 0 ? NaN : calcPrev / num; break;
          default: result = num;
        }
        setCalcDisplay(String(isNaN(result) ? 'Error' : result));
        setCalcPrev(isNaN(result) ? 0 : result);
        setCalcOp(key);
        setCalcWaiting(true);
      } else {
        setCalcPrev(num);
        setCalcOp(key);
        setCalcWaiting(true);
      }
      return;
    }

    if (key === '±') {
      if (calcDisplay !== '0' && calcDisplay !== 'Error') {
        setCalcDisplay(calcDisplay.startsWith('-') ? calcDisplay.slice(1) : '-' + calcDisplay);
      }
      return;
    }

    if (key === '%') {
      const num = parseFloat(calcDisplay);
      setCalcDisplay(String(num / 100));
      return;
    }
  };

  // ============ HANDLE CALC CLICK ============
  const handleCalcClick = (e) => {
    const btn = e.currentTarget;
    const value = btn.dataset.value;
    const action = btn.dataset.action;

    if (action === 'ac') {
      setCalcDisplay('0');
      setCalcPrev(null);
      setCalcOp(null);
      setCalcWaiting(false);
      setCalcSecret('');
      return;
    }

    if (action === 'equals') {
      if (calcDisplay === pin) {
        setUnlocked(true);
        setCalcDisplay('0');
        setCalcSecret('');
        setCalcPrev(null);
        setCalcOp(null);
        setCalcWaiting(false);
        loadData();
        return;
      }
      
      if (calcOp && !calcWaiting) {
        const num = parseFloat(calcDisplay);
        let result;
        switch(calcOp) {
          case '+': result = calcPrev + num; break;
          case '-': result = calcPrev - num; break;
          case '×': result = calcPrev * num; break;
          case '*': result = calcPrev * num; break;
          case '÷': result = num === 0 ? NaN : calcPrev / num; break;
          case '/': result = num === 0 ? NaN : calcPrev / num; break;
          default: result = num;
        }
        setCalcDisplay(isNaN(result) ? 'Error' : String(result));
        setCalcPrev(null);
        setCalcOp(null);
        setCalcWaiting(false);
        setCalcSecret('');
        // === GLOW EFFECT ===
        setCalcGlow(true);
        setTimeout(() => setCalcGlow(false), 500);
        return;
      }
      setCalcSecret('');
      return;
    }

    if (action === 'backspace') {
      setCalcDisplay(calcDisplay.length > 1 ? calcDisplay.slice(0, -1) : '0');
      return;
    }

    if (value !== undefined) {
      if (['+', '-', '*', '/'].includes(value)) {
        const num = parseFloat(calcDisplay);
        if (calcOp && !calcWaiting) {
          let result;
          switch(calcOp) {
            case '+': result = calcPrev + num; break;
            case '-': result = calcPrev - num; break;
            case '*': result = calcPrev * num; break;
            case '/': result = num === 0 ? NaN : calcPrev / num; break;
            default: result = num;
          }
          setCalcDisplay(String(isNaN(result) ? 'Error' : result));
          setCalcPrev(isNaN(result) ? 0 : result);
        } else {
          setCalcPrev(num);
        }
        setCalcOp(value);
        setCalcWaiting(true);
        setCalcSecret('');
        return;
      }
      
      if (calcDisplay === '0' || calcDisplay === 'Error') {
        setCalcDisplay(value);
      } else {
        setCalcDisplay(calcDisplay + value);
      }
      return;
    }

    if (action === 'sin') setCalcDisplay(calcDisplay + 'sin(');
    if (action === 'cos') setCalcDisplay(calcDisplay + 'cos(');
    if (action === 'tan') setCalcDisplay(calcDisplay + 'tan(');
    if (action === 'log') setCalcDisplay(calcDisplay + 'log(');
    if (action === 'ln') setCalcDisplay(calcDisplay + 'ln(');
    if (action === 'sqrt') setCalcDisplay(calcDisplay + 'sqrt(');
    if (action === 'square') setCalcDisplay('(' + calcDisplay + ')**2');
    if (action === 'cube') setCalcDisplay('(' + calcDisplay + ')**3');
    if (action === 'pi') setCalcDisplay(calcDisplay + Math.PI);
    if (action === 'euler') setCalcDisplay(calcDisplay + Math.E);
    if (action === 'negate') {
      if (calcDisplay !== '0') {
        setCalcDisplay(calcDisplay.startsWith('-') ? calcDisplay.slice(1) : '-' + calcDisplay);
      }
    }
    if (action === 'percent') setCalcDisplay('(' + calcDisplay + ')/100');
    if (action === 'factorial') {
      const num = parseInt(calcDisplay);
      if (num >= 0 && num <= 170) {
        let r = 1;
        for (let i = 2; i <= num; i++) r *= i;
        setCalcDisplay(String(r));
      }
    }
    if (action === 'lparen') {
      if (calcDisplay === '0') setCalcDisplay('(');
      else setCalcDisplay(calcDisplay + '(');
    }
    if (action === 'rparen') setCalcDisplay(calcDisplay + ')');
  };

  // ============ POSTS ============
  const fetchPosts = useCallback(async (cat) => {
    try {
      const data = await api.get(cat === 'all' ? '/posts' : `/posts/category/${cat}`);
      setPosts(data);
    } catch (err) {
      console.error('Failed to fetch posts:', err);
    }
  }, []);

  useEffect(() => {
    if (unlocked) fetchPosts(category);
  }, [category, unlocked, fetchPosts]);

  const createPost = async () => {
    if (postText.trim().length < 3) return;
    try {
      const newPost = await api.post('/posts', { category: postCategory, text: postText.trim(), anonId });
      setPosts(prev => [newPost, ...prev]);
      setShowPostModal(false);
      setPostText('');
      toast('Posted anonymously');
    } catch (err) {
      console.error('Failed to create post:', err);
      toast('Failed to create post');
    }
  };

  const deletePost = async (id) => {
    try {
      await api.delete(`/posts/${id}`);
      setPosts(prev => prev.filter(p => p.id !== id));
      toast('Post deleted');
    } catch (err) {
      console.error('Failed to delete post:', err);
      toast('Failed to delete post');
    }
  };

  const updatePost = async (id, text) => {
    try {
      const updated = await api.put(`/posts/${id}`, { text });
      setPosts(prev => prev.map(p => p.id === id ? updated : p));
      toast('Post updated');
    } catch (err) {
      console.error('Failed to update post:', err);
      toast('Failed to update post');
    }
  };

  const addReply = async (postId, text) => {
    try {
      const reply = await api.post(`/posts/${postId}/replies`, { text, anonId });
      setPosts(prev => prev.map(p => {
        if (p.id === postId) {
          return { ...p, replies: [...p.replies, reply] };
        }
        return p;
      }));
      setReplyDrafts(prev => ({ ...prev, [postId]: '' }));
      setOpenReplies(prev => ({ ...prev, [postId]: true }));
      toast('Reply added');
    } catch (err) {
      console.error('Failed to add reply:', err);
      toast('Failed to add reply');
    }
  };

  const deleteReply = async (postId, replyId) => {
    try {
      await api.delete(`/posts/${postId}/replies/${replyId}`);
      setPosts(prev => prev.map(p => {
        if (p.id === postId) {
          return { ...p, replies: p.replies.filter(r => r.id !== replyId) };
        }
        return p;
      }));
      toast('Reply deleted');
    } catch (err) {
      console.error('Failed to delete reply:', err);
      toast('Failed to delete reply');
    }
  };

  const updateReply = async (postId, replyId, text) => {
    try {
      const updated = await api.put(`/posts/${postId}/replies/${replyId}`, { text });
      setPosts(prev => prev.map(p => {
        if (p.id === postId) {
          return { ...p, replies: p.replies.map(r => r.id === replyId ? updated : r) };
        }
        return p;
      }));
      toast('Reply updated');
    } catch (err) {
      console.error('Failed to update reply:', err);
      toast('Failed to update reply');
    }
  };

  const toggleReplies = (postId) => {
    setOpenReplies(prev => ({ ...prev, [postId]: !prev[postId] }));
  };

  const submitReply = (postId) => {
    const text = (replyDrafts[postId] || '').trim();
    if (!text) return;
    addReply(postId, text);
  };

  // ============ CONTACTS ============
  const createContact = async (name, phone, type) => {
    try {
      const newContact = await api.post('/contacts', { name, phone, type });
      setContacts(prev => [...prev, newContact]);
      toast('Contact added');
    } catch (err) {
      console.error('Failed to create contact:', err);
      toast('Failed to add contact');
    }
  };

  const deleteContact = async (id) => {
    try {
      await api.delete(`/contacts/${id}`);
      setContacts(prev => prev.filter(c => c.id !== id));
      toast('Contact removed');
    } catch (err) {
      console.error('Failed to delete contact:', err);
      toast('Failed to delete contact');
    }
  };

  // ============ SOS ============
  const triggerSOS = () => {
    if (!navigator.geolocation) {
      setSosStatus("This browser can't access GPS.");
      return;
    }
    setSosStatus('📡 Getting your location…');
    navigator.geolocation.getCurrentPosition(
      async (pos) => {
        const { latitude: lat, longitude: lng } = pos.coords;
        setSosLocation({ lat, lng });
        setSosStatus(`📍 Location captured (±${Math.round(pos.coords.accuracy)}m)`);
        
        try {
          const res = await fetch(`https://nominatim.openstreetmap.org/reverse?format=json&lat=${lat}&lon=${lng}&zoom=16`);
          const data = await res.json();
          const address = data.display_name || null;
          setSosLocation(prev => ({ ...prev, address }));
          setSosStatus(`✅ Location ready: ${address || `${lat.toFixed(5)}, ${lng.toFixed(5)}`}`);
          await api.post('/soslogs', { lat, lng, address });
          const logs = await api.get('/soslogs');
          setSosLog(logs);
        } catch (err) {
          setSosStatus(`✅ Location saved at ${lat.toFixed(5)}, ${lng.toFixed(5)}`);
          await api.post('/soslogs', { lat, lng, address: null });
          const logs = await api.get('/soslogs');
          setSosLog(logs);
        }
      },
      (err) => {
        setSosStatus(`Location unavailable (${err.message})`);
      },
      { enableHighAccuracy: true, timeout: 12000 }
    );
  };

  const buildLocationMsg = () => {
    if (!sosLocation) return null;
    const osm = `https://www.openstreetmap.org/?mlat=${sosLocation.lat}&mlon=${sosLocation.lng}#map=17/${sosLocation.lat}/${sosLocation.lng}`;
    return `🚨 SOS — I need help.\nMy location: ${sosLocation.address || (sosLocation.lat.toFixed(5) + ', ' + sosLocation.lng.toFixed(5))}\nMap: ${osm}`;
  };

  const shareLocation = () => {
    const msg = buildLocationMsg();
    if (!msg) { toast('Trigger SOS first'); return; }
    if (navigator.share) {
      navigator.share({ title: 'Emergency location', text: msg }).catch(() => {});
    } else {
      navigator.clipboard?.writeText(msg);
      toast('Location copied');
    }
  };

  // ============ EXPORT / WIPE ============
  const exportData = async () => {
    try {
      const data = await api.get('/export');
      const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = 'aura-export.json';
      a.click();
      URL.revokeObjectURL(url);
      toast('Export downloaded');
    } catch (err) {
      console.error('Export failed:', err);
      toast('Export failed');
    }
  };

  const wipeData = async () => {
    try {
      await api.delete('/wipe');
      setPosts([]);
      setContacts([]);
      setSosLog([]);
      toast('All data wiped');
    } catch (err) {
      console.error('Wipe failed:', err);
      toast('Wipe failed');
    }
  };

  // ============ CHANGE PIN ============
  const changePin = async () => {
    if (newPin.length < 4) {
      setPinError('PIN must be at least 4 digits');
      return;
    }
    if (newPin !== confirmPin) {
      setPinError('PINs do not match');
      return;
    }
    try {
      await api.put('/config/pin', { pin: newPin });
      setPin(newPin);
      setShowPinModal(false);
      setNewPin('');
      setConfirmPin('');
      setPinError('');
      toast('✅ PIN changed successfully!');
    } catch (err) {
      setPinError('Failed to change PIN');
    }
  };

  // ============ HELPERS ============
  const timeAgo = (ts) => {
    const s = Math.floor((Date.now() - ts) / 1000);
    if (s < 60) return 'just now';
    if (s < 3600) return Math.floor(s / 60) + 'm ago';
    if (s < 86400) return Math.floor(s / 3600) + 'h ago';
    return Math.floor(s / 86400) + 'd ago';
  };

  const escapeHtml = (str) => {
    const map = { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' };
    return str.replace(/[&<>"']/g, m => map[m]);
  };

  // ============ RENDER ============

  // Calculator
  if (!unlocked) {
    return (
      <div id="stage">
        <div id="phone">
          <div className="calc-screen">
            <div className="calc-clock">{new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</div>
            <div className="calc-display-wrap">
              <div className={`calc-display ${calcGlow ? 'glow' : ''}`}>{calcDisplay}</div>
            </div>
            <div className="calc-pad">
              {/* Row 1: sin, cos, tan, log, sqrt */}
              <button className="calc-btn calc-fn" data-action="sin" onClick={handleCalcClick}>sin</button>
              <button className="calc-btn calc-fn" data-action="cos" onClick={handleCalcClick}>cos</button>
              <button className="calc-btn calc-fn" data-action="tan" onClick={handleCalcClick}>tan</button>
              <button className="calc-btn calc-fn" data-action="log" onClick={handleCalcClick}>log</button>
              <button className="calc-btn calc-fn" data-action="sqrt" onClick={handleCalcClick}>√</button>
              <button className="calc-btn calc-special" data-action="pi" onClick={handleCalcClick}>π</button>
              <button className="calc-btn calc-special" data-action="euler" onClick={handleCalcClick}>e</button>
              <button className="calc-btn calc-fn" data-action="lparen" onClick={handleCalcClick}>(</button>
              <button className="calc-btn calc-fn" data-action="rparen" onClick={handleCalcClick}>)</button>
              <button className="calc-btn calc-clear" data-action="ac" onClick={handleCalcClick}>AC</button>

              {/* Row 2: 7, 8, 9, ÷ */}
              <button className="calc-btn calc-number" data-value="7" onClick={handleCalcClick}>7</button>
              <button className="calc-btn calc-number" data-value="8" onClick={handleCalcClick}>8</button>
              <button className="calc-btn calc-number" data-value="9" onClick={handleCalcClick}>9</button>
              <button className="calc-btn calc-operator" data-value="/" onClick={handleCalcClick}>÷</button>

              {/* Row 3: 4, 5, 6, × */}
              <button className="calc-btn calc-number" data-value="4" onClick={handleCalcClick}>4</button>
              <button className="calc-btn calc-number" data-value="5" onClick={handleCalcClick}>5</button>
              <button className="calc-btn calc-number" data-value="6" onClick={handleCalcClick}>6</button>
              <button className="calc-btn calc-operator" data-value="*" onClick={handleCalcClick}>×</button>

              {/* Row 4: 1, 2, 3, − */}
              <button className="calc-btn calc-number" data-value="1" onClick={handleCalcClick}>1</button>
              <button className="calc-btn calc-number" data-value="2" onClick={handleCalcClick}>2</button>
              <button className="calc-btn calc-number" data-value="3" onClick={handleCalcClick}>3</button>
              <button className="calc-btn calc-operator" data-value="-" onClick={handleCalcClick}>−</button>

              {/* Row 5: 0, ., =, + */}
              <button className="calc-btn calc-number" data-value="0" onClick={handleCalcClick}>0</button>
              <button className="calc-btn calc-number" data-value="." onClick={handleCalcClick}>.</button>
              <button className="calc-btn calc-equals" data-action="equals" onClick={handleCalcClick}>=</button>
              <button className="calc-btn calc-operator" data-value="+" onClick={handleCalcClick}>+</button>
            </div>
          </div>
        </div>
      </div>
    );
  }

  // ============ SANCTUARY ============
  return (
    <div id="stage">
      <div id="phone">
        <div id="sanctuary">
          <div className="aura-glow">
            <span></span><span></span><span></span>
          </div>

          <div className="topbar">
            <div className="brand"><span className="dot"></span> AURA</div>
            <div className="topbar-actions">
              <button className="icon-btn" onClick={() => setView('settings')}>⚙</button>
              <button className="icon-btn" onClick={() => setUnlocked(false)}>–</button>
            </div>
          </div>

          <div className="content">
            {/* FEED */}
            <div className={`view ${view === 'feed' ? 'active' : ''}`}>
              <div className="hero">
                <h1>You're safe here.</h1>
                <p>Share anything, anonymously. No names, no accounts — just people who understand.</p>
              </div>
              <div className="pills">
                {['all', 'mental', 'abuse', 'bully'].map(c => (
                  <button key={c} className={`pill ${category === c ? 'active' : ''}`} onClick={() => setCategory(c)}>
                    {c === 'all' ? '🌐 All' : c === 'mental' ? '🧠 Mental Health' : c === 'abuse' ? '🛡 Abuse Support' : '🕊 Bullying'}
                  </button>
                ))}
              </div>
              <div className="compose-bar" onClick={() => setShowPostModal(true)}>
                <span>Share your story anonymously…</span>
                <button>Post</button>
              </div>
              <div className="section-label">Community feed</div>
              <div className="feed-list">
                {posts.length === 0 ? (
                  <div className="empty-state"><div className="glyph">🌙</div>No posts yet.<br/>Be the first to share.</div>
                ) : (
                  posts.map(post => {
                    const catColors = { mental: 'tag-mental', abuse: 'tag-abuse', bully: 'tag-bully' };
                    const catIcons = { mental: '🧠', abuse: '🛡', bully: '🕊' };
                    const catNames = { mental: 'Mental Health', abuse: 'Abuse Support', bully: 'Bullying' };
                    const isMine = post.anonId === anonId;
                    const replies = post.replies || [];
                    const isOpen = !!openReplies[post.id];

                    return (
                      <div key={post.id} className="post-card">
                        <div className="post-top">
                          <span className={`post-tag ${catColors[post.category]}`}>
                            {catIcons[post.category]} {catNames[post.category]}
                          </span>
                          <span className="post-meta">
                            <span className="anon-avatar">🕶</span>
                            {post.anonId}{isMine && ' · you'} · {timeAgo(post.ts)}{post.edited && ' · edited'}
                          </span>
                        </div>
                        <div className="post-text">{escapeHtml(post.text)}</div>
                        <div className="post-actions">
                          <button className="reply-toggle" onClick={() => toggleReplies(post.id)}>
                            💬 {replies.length} {replies.length === 1 ? 'reply' : 'replies'}
                          </button>
                          <button onClick={() => {
                            const text = `"${post.text}" — shared via AURA Sanctuary`;
                            if (navigator.share) navigator.share({ title: 'AURA', text }).catch(() => {});
                            else { navigator.clipboard?.writeText(text); toast('Copied'); }
                          }}>📤 Share</button>
                          <span className="spacer"></span>
                          {isMine && (
                            <>
                              <button onClick={() => {
                                const newText = prompt('Edit your post:', post.text);
                                if (newText && newText.trim()) updatePost(post.id, newText.trim());
                              }}>✏️ Edit</button>
                              <button className="danger-txt" onClick={() => {
                                setConfirmData({ title: 'Delete this post?', sub: 'This will remove your post and all replies.', onConfirm: () => deletePost(post.id) });
                                setShowConfirm(true);
                              }}>🗑</button>
                            </>
                          )}
                        </div>
                        <div className={`replies ${isOpen ? '' : 'hidden'}`}>
                          {replies.map(reply => (
                            <div key={reply.id} className="reply">
                              <div className="reply-top">
                                <span className="reply-meta">
                                  🕶 {reply.anonId}{reply.anonId === anonId && ' · you'} · {timeAgo(reply.ts)}{reply.edited && ' · edited'}
                                </span>
                              </div>
                              <div className="reply-text">{escapeHtml(reply.text)}</div>
                              {reply.anonId === anonId && (
                                <div className="reply-actions">
                                  <button onClick={() => {
                                    const newText = prompt('Edit reply:', reply.text);
                                    if (newText && newText.trim()) updateReply(post.id, reply.id, newText.trim());
                                  }}>Edit</button>
                                  <button className="danger-txt" onClick={() => deleteReply(post.id, reply.id)}>Delete</button>
                                </div>
                              )}
                            </div>
                          ))}
                          <div className="reply-input-row">
                            <input
                              type="text"
                              placeholder="Write a reply…"
                              className="reply-input"
                              maxLength="500"
                              value={replyDrafts[post.id] || ''}
                              onChange={(e) => setReplyDrafts(prev => ({ ...prev, [post.id]: e.target.value }))}
                              onKeyDown={(e) => { if (e.key === 'Enter') submitReply(post.id); }}
                            />
                            <button onClick={() => submitReply(post.id)}>Send</button>
                          </div>
                        </div>
                      </div>
                    );
                  })
                )}
              </div>
            </div>

            {/* CONTACTS */}
            <div className={`view ${view === 'contacts' ? 'active' : ''}`}>
              <div className="hero">
                <h1>Trusted contacts</h1>
                <p>Add people or authorities you want to reach in an emergency.</p>
              </div>
              <div className="add-contact-form">
                <div className="row">
                  <input type="text" id="cName" placeholder="Name (e.g. Sister, Police)" />
                </div>
                <div className="row">
                  <input type="tel" id="cPhone" placeholder="Phone number" />
                  <select id="cType">
                    <option value="trusted">Trusted person</option>
                    <option value="authority">Authority</option>
                  </select>
                </div>
                <button onClick={() => {
                  const name = document.getElementById('cName').value.trim();
                  const phone = document.getElementById('cPhone').value.trim();
                  const type = document.getElementById('cType').value;
                  if (!name || !phone) { toast('Add a name and phone number'); return; }
                  createContact(name, phone, type);
                  document.getElementById('cName').value = '';
                  document.getElementById('cPhone').value = '';
                }}>+ Add contact</button>
              </div>
              <div className="contacts-list">
                {contacts.length === 0 ? (
                  <div className="empty-state"><div className="glyph">📇</div>No contacts yet.</div>
                ) : (
                  contacts.map(c => (
                    <div key={c.id} className="contact-row">
                      <div className="contact-avatar">{c.type === 'authority' ? '🏛' : '💛'}</div>
                      <div className="contact-info">
                        <div className="cn">{escapeHtml(c.name)}</div>
                        <div className="cp">{escapeHtml(c.phone)}</div>
                      </div>
                      <div className="contact-btns">
                        <button className="round-btn call" onClick={() => window.location.href = `tel:${c.phone.replace(/\s+/g, '')}`}>📞</button>
                        <button className="round-btn sms" onClick={() => window.location.href = `sms:${c.phone.replace(/\s+/g, '')}`}>💬</button>
                        <button className="round-btn del" onClick={() => {
                          setConfirmData({ title: `Remove ${c.name}?`, sub: '', onConfirm: () => deleteContact(c.id) });
                          setShowConfirm(true);
                        }}>✕</button>
                      </div>
                    </div>
                  ))
                )}
              </div>
            </div>

            {/* SOS */}
            <div className={`view ${view === 'sos' ? 'active' : ''}`}>
              <div className="sos-hero">
                <h1 style={{ fontFamily: 'var(--font-display)', fontSize: '22px', marginBottom: '6px' }}>Emergency SOS</h1>
                <p style={{ color: 'var(--muted)', fontSize: '12.5px' }}>Captures your location and gets it to the people who can help.</p>
              </div>
              <div className="sos-orb-wrap">
                <button className="sos-orb" onClick={triggerSOS}>
                  SOS
                  <small>PRESS TO ALERT</small>
                </button>
              </div>
              <div className="sos-status">{sosStatus}</div>
              {sosLocation && (
                <div id="sosMap" ref={el => {
                  if (el && !mapRef.current && sosLocation) {
                    const map = L.map(el).setView([sosLocation.lat, sosLocation.lng], 16);
                    L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', { maxZoom: 19 }).addTo(map);
                    L.marker([sosLocation.lat, sosLocation.lng]).addTo(map);
                    mapRef.current = map;
                    setTimeout(() => map.invalidateSize(), 200);
                  }
                }} style={{ height: '180px', borderRadius: '12px', overflow: 'hidden', marginBottom: '14px', border: '1px solid var(--card-bd)' }} />
              )}
              {sosLocation && (
                <button className="big-action share" onClick={shareLocation}>📤 Share location now</button>
              )}
              <div className="section-label">Notify a contact</div>
              <div className="sos-contact-list">
                {contacts.length === 0 ? (
                  <div className="empty-state" style={{ padding: '20px' }}>Add a contact first, from the Contacts tab.</div>
                ) : (
                  contacts.map(c => (
                    <div key={c.id} className="contact-row">
                      <div className="contact-avatar">{c.type === 'authority' ? '🏛' : '💛'}</div>
                      <div className="contact-info">
                        <div className="cn">{escapeHtml(c.name)}</div>
                        <div className="cp">{escapeHtml(c.phone)}</div>
                      </div>
                      <div className="contact-btns">
                        <button className="round-btn call" onClick={() => window.location.href = `tel:${c.phone.replace(/\s+/g, '')}`}>📞</button>
                        <button className="round-btn sms" onClick={() => {
                          const msg = buildLocationMsg();
                          if (!msg) { toast('Trigger SOS first'); return; }
                          window.location.href = `sms:${c.phone.replace(/\s+/g, '')}?body=${encodeURIComponent(msg)}`;
                        }}>📍</button>
                      </div>
                    </div>
                  ))
                )}
              </div>
              <div className="section-label">Recent SOS activity</div>
              <div className="sos-log-list">
                {sosLog.length === 0 ? (
                  <div className="empty-state" style={{ padding: '18px' }}>No SOS activity yet.</div>
                ) : (
                  sosLog.slice(0, 8).map(log => (
                    <div key={log.id} className="contact-row">
                      <div className="contact-avatar">🚨</div>
                      <div className="contact-info">
                        <div className="cn">{new Date(log.ts).toLocaleString()}</div>
                        <div className="cp">{escapeHtml(log.address || `${log.lat.toFixed(5)}, ${log.lng.toFixed(5)}`)}</div>
                      </div>
                    </div>
                  ))
                )}
              </div>
            </div>

            {/* SETTINGS */}
            <div className={`view ${view === 'settings' ? 'active' : ''}`}>
              <div className="hero">
                <h1>Settings</h1>
                <p>Everything here lives on the server.</p>
              </div>
              <div className="settings-group">
                <div className="settings-row">
                  <div>
                    <div className="st-label">Secret unlock code</div>
                    <div className="st-sub">Current PIN: {pin}</div>
                  </div>
                  <button className="mini-btn primary" onClick={() => setShowPinModal(true)}>Change</button>
                </div>
                <div className="settings-row">
                  <div>
                    <div className="st-label">Your anonymous ID</div>
                    <div className="st-sub">{anonId}</div>
                  </div>
                  <button className="mini-btn" style={{ background: 'rgba(255,255,255,.08)', color: 'var(--paper)' }} onClick={() => {
                    const newId = 'Anon-' + Math.random().toString(36).substr(2, 8);
                    setAnonId(newId);
                    toast('New ID generated');
                  }}>Rotate</button>
                </div>
              </div>
              <div className="settings-group">
                <div className="settings-row">
                  <div>
                    <div className="st-label">Export my data</div>
                    <div className="st-sub">Download posts, replies & contacts as a file</div>
                  </div>
                  <button className="mini-btn" style={{ background: 'rgba(255,255,255,.08)', color: 'var(--paper)' }} onClick={exportData}>Export</button>
                </div>
                <div className="settings-row">
                  <div>
                    <div className="st-label">Panic wipe</div>
                    <div className="st-sub">Erase every trace from the server instantly</div>
                  </div>
                  <button className="mini-btn danger" onClick={() => {
                    setConfirmData({ title: 'Wipe all data?', sub: 'This erases everything permanently.', onConfirm: wipeData });
                    setShowConfirm(true);
                  }}>Wipe</button>
                </div>
              </div>
              <div className="section-label">About AURA</div>
              <div className="about-block">
                AURA hides a private support space behind an ordinary-looking calculator. Once unlocked, you can post anonymously under Mental Health, Abuse Support or Bullying, read and reply to others, and trigger an SOS that captures your GPS location — using OpenStreetMap — and prepares it to reach your trusted contacts.
                <br /><br />
                This build uses a Node/Express backend to store posts, contacts and SOS logs persistently in a local JSON file.
                <br /><br />
                If you or someone you know is in immediate danger, please contact local emergency services directly.
              </div>
            </div>
          </div>

          {/* Bottom Nav */}
          <div className="bottomnav">
            {['feed', 'contacts', 'sos', 'settings'].map(v => (
              <button key={v} className={`navbtn ${view === v ? 'active' : ''} ${v === 'sos' ? 'sosnav' : ''}`} onClick={() => setView(v)}>
                <span className="ni">
                  {v === 'feed' && '🏠'}
                  {v === 'contacts' && '📇'}
                  {v === 'sos' && '🚨'}
                  {v === 'settings' && '⚙'}
                </span>
                {v === 'feed' && 'Sanctuary'}
                {v === 'contacts' && 'Contacts'}
                {v === 'sos' && 'SOS'}
                {v === 'settings' && 'Settings'}
              </button>
            ))}
          </div>
        </div>

        {/* Post Modal */}
        {showPostModal && (
          <div className="modal-overlay" onClick={(e) => { if (e.target === e.currentTarget) { setShowPostModal(false); setPostText(''); } }}>
            <div className="modal-sheet">
              <div className="modal-handle"></div>
              <h3 className="modal-title">Share anonymously</h3>
              <p className="modal-sub">No name, no login — just your words.</p>
              <div className="cat-choice">
                {['mental', 'abuse', 'bully'].map(c => (
                  <button key={c} className={postCategory === c ? 'sel' : ''} onClick={() => setPostCategory(c)}>
                    <span className="ci">{c === 'mental' ? '🧠' : c === 'abuse' ? '🛡' : '🕊'}</span>
                    {c === 'mental' ? 'Mental' : c === 'abuse' ? 'Abuse' : 'Bully'}
                  </button>
                ))}
              </div>
              <textarea 
                placeholder="What's on your mind? You're safe to say it here…" 
                maxLength="1200"
                value={postText}
                onChange={(e) => setPostText(e.target.value)}
              />
              <div className="char-count"><span>{postText.length}</span>/1200</div>
              <div className="anon-preview">👤 Will post as <b style={{ color: 'var(--paper)', marginLeft: '3px' }}>Anonymous</b></div>
              <button className="submit-btn" disabled={postText.trim().length < 3} onClick={createPost}>
                Post anonymously
              </button>
            </div>
          </div>
        )}

        {/* Confirm Modal */}
        {showConfirm && (
          <div className="modal-overlay center" onClick={(e) => { if (e.target === e.currentTarget) setShowConfirm(false); }}>
            <div className="modal-sheet">
              <h3 className="modal-title">{confirmData.title}</h3>
              <p className="modal-sub">{confirmData.sub}</p>
              <div className="confirm-actions">
                <button className="no" onClick={() => setShowConfirm(false)}>Cancel</button>
                <button className="yes" onClick={() => {
                  if (confirmData.onConfirm) confirmData.onConfirm();
                  setShowConfirm(false);
                }}>Yes, continue</button>
              </div>
            </div>
          </div>
        )}

        {/* PIN Change Modal */}
        {showPinModal && (
          <div className="modal-overlay center" onClick={(e) => { 
            if (e.target === e.currentTarget) { 
              setShowPinModal(false); 
              setNewPin('');
              setConfirmPin('');
              setPinError('');
            } 
          }}>
            <div className="modal-sheet">
              <h3 className="modal-title">Change Unlock Code</h3>
              <p className="modal-sub">Enter a new 4+ digit PIN</p>
              
              <div style={{ marginBottom: '12px' }}>
                <label style={{ color: 'var(--muted)', fontSize: '13px', display: 'block', marginBottom: '4px' }}>New PIN</label>
                <input
                  type="password"
                  value={newPin}
                  onChange={(e) => setNewPin(e.target.value)}
                  placeholder="Enter new PIN"
                  maxLength="6"
                  style={{
                    width: '100%',
                    padding: '10px 12px',
                    background: 'rgba(255,255,255,0.06)',
                    border: '1px solid var(--card-bd)',
                    borderRadius: '10px',
                    color: 'var(--paper)',
                    fontSize: '16px',
                    outline: 'none',
                    textAlign: 'center',
                    letterSpacing: '8px'
                  }}
                />
              </div>
              
              <div style={{ marginBottom: '16px' }}>
                <label style={{ color: 'var(--muted)', fontSize: '13px', display: 'block', marginBottom: '4px' }}>Confirm PIN</label>
                <input
                  type="password"
                  value={confirmPin}
                  onChange={(e) => setConfirmPin(e.target.value)}
                  placeholder="Confirm new PIN"
                  maxLength="6"
                  style={{
                    width: '100%',
                    padding: '10px 12px',
                    background: 'rgba(255,255,255,0.06)',
                    border: '1px solid var(--card-bd)',
                    borderRadius: '10px',
                    color: 'var(--paper)',
                    fontSize: '16px',
                    outline: 'none',
                    textAlign: 'center',
                    letterSpacing: '8px'
                  }}
                />
              </div>
              
              {pinError && (
                <div style={{ color: 'var(--danger)', fontSize: '13px', marginBottom: '12px', textAlign: 'center' }}>
                  ❌ {pinError}
                </div>
              )}
              
              <div className="confirm-actions">
                <button 
                  className="no" 
                  onClick={() => {
                    setShowPinModal(false);
                    setNewPin('');
                    setConfirmPin('');
                    setPinError('');
                  }}
                >
                  Cancel
                </button>
                <button 
                  className="yes" 
                  onClick={changePin}
                  style={{ background: 'var(--violet)', color: '#fff' }}
                >
                  Save PIN
                </button>
              </div>
            </div>
          </div>
        )}

        <div className={`toast ${showToast ? 'show' : ''}`}>{toastMsg}</div>
      </div>
    </div>
  );
}

export default App;
